'use client';

import * as React from 'react';
import { cn } from '@/lib/utils';
import { Button } from '../button/Button';
import { Input } from '../input/Input';

export type FilterBarProps = React.HTMLAttributes<HTMLDivElement> & {
  /** Controlled search text. */
  searchValue?: string;
  onSearchChange?: (value: string) => void;
  /** Search placeholder; the search box is hidden when omitted. */
  searchPlaceholder?: string;
  /** Rendered after the search box — selects, toggles, date pickers. */
  children?: React.ReactNode;
  /** Shows a reset button when provided (pass the active filter count for the label). */
  onReset?: () => void;
  activeCount?: number;
  /** Opens a filter panel or mobile filter drawer. */
  onOpenFilters?: () => void;
  /** Filter button label. Default "Filters". */
  filtersLabel?: string;
  /** Result count shown before the trailing slot. */
  resultsCount?: number;
  /** Noun for the result count. Default "results". */
  resultsLabel?: string;
  /** Rendered at the far right (bulk actions, column settings). */
  trailing?: React.ReactNode;
};

/**
 * Horizontal filter strip for list pages: search field, filter controls and
 * a reset affordance. Scrolls horizontally on narrow screens instead of
 * wrapping into a tall stack.
 */
export const FilterBar = React.forwardRef<HTMLDivElement, FilterBarProps>(function FilterBar(
  {
    searchValue,
    onSearchChange,
    searchPlaceholder = 'Search…',
    onReset,
    activeCount = 0,
    onOpenFilters,
    filtersLabel = 'Filters',
    resultsCount,
    resultsLabel = 'results',
    trailing,
    className,
    children,
    ...props
  },
  ref
) {
  return (
    <div
      ref={ref}
      role="search"
      className={cn(
        'flex flex-wrap items-center gap-2 rounded-lg border border-border bg-card p-2',
        className
      )}
      {...props}
    >
      {onSearchChange !== undefined && (
        <Input
          type="search"
          value={searchValue}
          onChange={(event) => onSearchChange(event.target.value)}
          placeholder={searchPlaceholder}
          aria-label={searchPlaceholder}
          className="h-9 w-full min-w-40 flex-1 sm:w-auto"
        />
      )}
      <div className="flex flex-wrap items-center gap-2">{children}</div>
      {onOpenFilters && (
        <Button type="button" variant="outline" size="sm" onClick={onOpenFilters}>
          {filtersLabel}
          {activeCount > 0 ? ` (${activeCount})` : ''}
        </Button>
      )}
      {onReset && (
        <Button type="button" variant="ghost" size="sm" onClick={onReset}>
          Reset{activeCount > 0 ? ` (${activeCount})` : ''}
        </Button>
      )}
      {resultsCount !== undefined && (
        <span className="ml-auto text-sm text-muted-foreground">
          {resultsCount} {resultsLabel}
        </span>
      )}
      {trailing && <div className={cn('flex items-center gap-2', resultsCount === undefined && 'ml-auto')}>{trailing}</div>}
    </div>
  );
});

{
  "id": "filter-bar",
  "name": "FilterBar",
  "tier": "molecule",
  "description": "List-page filter strip: search field, filter controls, reset affordance and trailing actions.",
  "designIntent": "Filter rows drift: some pages wrap, some scroll, resets appear inconsistently. FilterBar fixes the order (search → filters → reset → trailing) and keeps the strip compact on narrow screens.",
  "props": [
    {
      "name": "searchValue",
      "type": "string",
      "required": false,
      "description": "Controlled search text."
    },
    {
      "name": "onSearchChange",
      "type": "(value: string) => void",
      "required": false,
      "description": "Fires on each keystroke; hides the search box when omitted."
    },
    {
      "name": "searchPlaceholder",
      "type": "string",
      "required": false,
      "defaultValue": "Search…",
      "description": "Search input placeholder (also its accessible name)."
    },
    {
      "name": "onReset",
      "type": "() => void",
      "required": false,
      "description": "Shows a reset button when provided."
    },
    {
      "name": "activeCount",
      "type": "number",
      "required": false,
      "defaultValue": "0",
      "description": "Active filter count appended to the reset and filter labels."
    },
    {
      "name": "onOpenFilters",
      "type": "() => void",
      "required": false,
      "description": "Shows a Filters button and opens a filter panel or mobile drawer."
    },
    {
      "name": "filtersLabel",
      "type": "string",
      "required": false,
      "defaultValue": "Filters",
      "description": "Filter button label."
    },
    {
      "name": "resultsCount",
      "type": "number",
      "required": false,
      "description": "Result count shown before the trailing slot."
    },
    {
      "name": "resultsLabel",
      "type": "string",
      "required": false,
      "defaultValue": "results",
      "description": "Noun for the result count."
    },
    {
      "name": "trailing",
      "type": "ReactNode",
      "required": false,
      "description": "Far-right actions (bulk actions, column settings)."
    }
  ],
  "examples": [
    {
      "title": "List filters",
      "code": "<FilterBar\n  searchValue={query}\n  onSearchChange={setQuery}\n  searchPlaceholder=\"Search students\"\n  onReset={resetFilters}\n  activeCount={activeFilters}\n  onOpenFilters={() => setPanelOpen(true)}\n  resultsCount={312}\n>\n  <Select label=\"Status\" options={statusOptions} />\n</FilterBar>",
      "description": "Search, filters, reset and count in one strip."
    }
  ],
  "antiPatterns": [
    {
      "title": "Don't put the primary action in the bar",
      "explanation": "FilterBar is for narrowing; creation actions belong in PageHeader actions.",
      "example": "// Avoid\n<FilterBar trailing={<Button>New class</Button>} />\n\n// Prefer\n<PageHeader actions={<Button>New class</Button>} />"
    }
  ],
  "accessibility": [
    {
      "feature": "Search landmark",
      "implementation": "Wraps controls in role=search; the search input is labelled by its placeholder",
      "userRequirements": "Provide a descriptive placeholder"
    }
  ],
  "contentGuidelines": [
    {
      "contentType": "Placeholder",
      "guidelines": [
        "Name the collection being searched"
      ],
      "goodExamples": [
        "Search students"
      ],
      "badExamples": [
        "Search…"
      ]
    }
  ],
  "compositionRules": [
    {
      "component": "Select",
      "relationship": "Filter controls render in children",
      "example": "<FilterBar><Select … /></FilterBar>"
    }
  ],
  "relatedComponents": [
    "DataTable",
    "Select",
    "Input",
    "PageHeader"
  ],
  "package": "@slipstream-ui/core",
  "importPath": "@slipstream-ui/core",
  "version": "0.6.1",
  "sourceDir": "filter-bar",
  "exportName": "FilterBar"
}
